import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.D7WGirly.js";const m=JSON.parse('{"title":"AI SDK conversation persistence","description":"","frontmatter":{},"headers":[],"relativePath":"ai/conversation-persistence.md","filePath":"ai/conversation-persistence.md"}'),i={name:"ai/conversation-persistence.md"};function n(r,e,d,l,c,p){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="ai-sdk-conversation-persistence" tabindex="-1">AI SDK conversation persistence <a class="header-anchor" href="#ai-sdk-conversation-persistence" aria-label="Permalink to &quot;AI SDK conversation persistence&quot;">​</a></h1><p>Keep complete AI SDK message history in encrypted storage. The recipe validates messages on reload and saves only completed generations, while preserving message IDs, parts, tool values, data, and metadata.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Follow <a href="./../ai-integrations.html#run-the-examples">AI integration setup</a> and configure <a href="./encrypted-memory.html">encrypted memory</a>. AI SDK is installed in the separate example app, not in <code>encrypt-rsa</code>. The recipe targets the version pinned by that app&#39;s lockfile.</p><h2 id="load-generate-and-save" tabindex="-1">Load, generate, and save <a class="header-anchor" href="#load-generate-and-save" aria-label="Permalink to &quot;Load, generate, and save&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Encrypted history</span></span>
<span class="line"><span>  → decrypt and validate UI messages</span></span>
<span class="line"><span>  → convert messages and call the model</span></span>
<span class="line"><span>  → consume the full server stream</span></span>
<span class="line"><span>  → validate completed history</span></span>
<span class="line"><span>  → encrypt and save with a revision check</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Example function</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>loadMessages(memory, context, id, validation)</code></td><td>Reads encrypted memory and validates complete <code>UIMessage</code> values against application schemas</td></tr><tr><td><code>persistConversation(options)</code></td><td>Runs generation, consumes the stream, and saves completed history using the expected revision</td></tr><tr><td><code>jsonData(value)</code></td><td>Omits optional undefined object fields while rejecting unsupported or lossy JSON values</td></tr></tbody></table><p>These functions are defined in <a href="https://github.com/miladezzat/encrypt-rsa/blob/master/examples/ai-integrations/persistence.mjs" target="_blank" rel="noreferrer"><code>persistence.mjs</code></a>. They are example helpers, not package-root APIs. Pass validated user messages to <code>persistConversation</code> along with the loaded history, trusted context, current revision, configured model/tools, and the same validation schemas used on reload.</p><h2 id="persistence-and-validation-policy" tabindex="-1">Persistence and validation policy <a class="header-anchor" href="#persistence-and-validation-policy" aria-label="Permalink to &quot;Persistence and validation policy&quot;">​</a></h2><p>The separate <code>persistence.mjs</code> recipe:</p><ol><li>Decrypts and validates full <code>UIMessage</code> objects using <code>validateUIMessages</code>, including declared metadata/data schemas and tool schemas.</li><li>Converts validated UI messages with <code>convertToModelMessages(original, { tools })</code> before <code>streamText</code>, using each configured tool&#39;s <code>toModelOutput</code> converter for replayed results.</li><li>Owns consumption of the full server stream with <code>toUIMessageStream</code> and <code>readUIMessageStream</code>. A failed UI delivery hook disables delivery while consumption continues.</li><li>Stores full completed history (IDs, parts, tool input/output, data, metadata) only when the SDK reports a completed outcome. Failures/aborts preserve existing history. A revision conflict rejects instead of overwriting another request.</li></ol><h3 id="preserve-complete-message-values" tabindex="-1">Preserve complete message values <a class="header-anchor" href="#preserve-complete-message-values" aria-label="Permalink to &quot;Preserve complete message values&quot;">​</a></h3><p>SDK optional undefined object fields are omitted explicitly; other non-JSON values reject. Do not flatten history into text or silently reset invalid history. Declare the same schemas/tools on reload. Validate tool input/output and authorize tool execution independently; encrypting a tool result does not make it trustworthy. The recipe supports the pinned SDK version, not an untested generic adapter for every provider/version.</p><p>Pass the same tool definitions to <code>loadMessages(..., { tools })</code> and <code>persistConversation({ ..., tools })</code>. A tool can use <code>toModelOutput</code> to format its stored result for the model, including a custom text or multimodal representation. Conversion changes the model prompt only; encrypted UI history keeps the complete original result for later validation and display. A converter failure rejects before generation starts or history is updated.</p><h3 id="own-the-server-task" tabindex="-1">Own the server task <a class="header-anchor" href="#own-the-server-task" aria-label="Permalink to &quot;Own the server task&quot;">​</a></h3><p>Keep the server task alive using the host&#39;s background-task facility and await/report the persistence promise. A client disconnect must stop UI delivery, not cancel that task. An explicit server abort cancels generation and does not save partial history. For long-lived jobs use a durable worker; serverless processes may end after the response. Add idempotency, conflict resolution, retries, retention/deletion, rate limits, and durable storage for a deployed application.</p><h3 id="understand-provider-access" tabindex="-1">Understand provider access <a class="header-anchor" href="#understand-provider-access" aria-label="Permalink to &quot;Understand provider access&quot;">​</a></h3><p>Plaintext is available to the application and to any provider receiving model messages. At-rest encryption does not provide end-to-end secrecy from an AI provider. Minimize/redact submitted data and apply your provider/privacy policy. Never send private keys or credentials to a model.</p><h2 id="verify-the-integration-locally" tabindex="-1">Verify the integration locally <a class="header-anchor" href="#verify-the-integration-locally" aria-label="Permalink to &quot;Verify the integration locally&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/ai-integrations</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/ai-integrations</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>Fixture tests exercise completed history, metadata/tool validation, replayed tool output conversion, converter failures, UI disconnects, failed/aborted generation, and write conflicts. They make no paid provider calls. See the <a href="https://ai-sdk.dev/docs/ai-sdk-ui/chatbot-message-persistence" target="_blank" rel="noreferrer">AI SDK persistence documentation</a> when adapting the recipe to your pinned SDK version.</p><p>Continue with the <a href="./docs-assistant.html">docs assistant</a> for approved JSON and signed-message code templates.</p>`,22)])])}const u=a(i,[["render",n]]);export{m as __pageData,u as default};
